//! Dagger workspace and Dang module generation.

mod expanded;
mod services;

use std::collections::BTreeMap;
use std::fmt::Write as _;
use std::path::{Component, Path, PathBuf};

use cuenv_ci::emitter::{Emitter, EmitterError, EmitterResult};
use cuenv_ci::ir::IntermediateRepresentation;
use cuenv_core::ci::PipelineMode;
use cuenv_core::manifest::Project;

use crate::config::DaggerCiConfig;

const GENERATED_HEADER: &str = "# Code generated by cuenv. DO NOT EDIT.\n";
const DEFAULT_ENGINE_VERSION: &str = "v1.0.0-beta.28";
const CONTAINER_ROOT: &str = "/cuenv-workspace";

/// A generated file relative to the repository.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct EmittedFile {
    /// File path relative to the repository.
    pub relative_path: PathBuf,
    /// Generated file contents.
    pub content: String,
}

/// A compiled pipeline with its owning project and source location.
#[derive(Debug, Clone, Copy)]
pub struct WorkspacePipeline<'a> {
    /// Compiled pipeline.
    pub ir: &'a IntermediateRepresentation,
    /// Project configuration, including task runtimes and services.
    pub project: Option<&'a Project>,
    /// Project directory relative to the Git root Dagger uses as its workspace.
    pub project_dir: &'a Path,
    /// CUE module directory relative to the Git root Dagger uses as its workspace.
    pub module_dir: &'a Path,
    /// CUE package used by thin checks.
    pub package: &'a str,
}

/// Emits Dagger workspace and Dang module files.
#[derive(Debug, Clone, Default)]
pub struct DaggerWorkspaceEmitter {
    /// Provider configuration from `ci.provider.dagger`.
    pub config: DaggerCiConfig,
}

impl DaggerWorkspaceEmitter {
    /// Create an emitter with the project's provider configuration.
    #[must_use]
    pub const fn new(config: DaggerCiConfig) -> Self {
        Self { config }
    }

    /// Emit the workspace config followed by the module files.
    ///
    /// # Errors
    ///
    /// Returns an error for invalid paths, names, or unsupported pipelines.
    pub fn emit_workspace(
        &self,
        pipelines: &[WorkspacePipeline<'_>],
    ) -> EmitterResult<Vec<EmittedFile>> {
        let module_name = self.config.module_name();
        let base = relative_path(Path::new(self.config.workspace_dir()))?;
        let default_module = format!(".dagger/modules/{module_name}");
        let module_dir = relative_path(Path::new(
            self.config
                .module_path
                .as_deref()
                .unwrap_or(&default_module),
        ))?;
        let module_source = format!("./{}", module_dir.display());
        let engine_version = self
            .config
            .engine_version
            .as_deref()
            .unwrap_or(DEFAULT_ENGINE_VERSION);
        let main = self.emit_module(pipelines)?;

        Ok(vec![
            EmittedFile {
                relative_path: base.join("dagger.toml"),
                content: format!(
                    "{GENERATED_HEADER}\n[modules.{module_name}]\nsource = {}\n",
                    literal(&module_source)
                ),
            },
            EmittedFile {
                relative_path: base.join(&module_dir).join("dagger-module.toml"),
                content: format!(
                    "{GENERATED_HEADER}\nname = {}\nengineVersion = {}\n\n[runtime]\nsource = \"dang\"\n",
                    literal(module_name),
                    literal(engine_version),
                ),
            },
            EmittedFile {
                relative_path: base.join(module_dir).join("main.dang"),
                content: main,
            },
        ])
    }

    /// Emit only the Dang source, as used by `cuenv ci --export dagger`.
    ///
    /// # Errors
    ///
    /// Returns an error if module metadata or a pipeline cannot be represented.
    pub fn emit_module(&self, pipelines: &[WorkspacePipeline<'_>]) -> EmitterResult<String> {
        let module_type = module_type(self.config.module_name())?;
        let mut out = format!("{GENERATED_HEADER}\ntype {module_type} {{\n");
        let mut projects = BTreeMap::new();

        for (index, pipeline) in pipelines.iter().enumerate() {
            let project_key = (
                pipeline.project_dir,
                pipeline.project.map(|project| project.name.as_str()),
            );
            let next_project_id = projects.len();
            let (project_id, render_services) = match projects.entry(project_key) {
                std::collections::btree_map::Entry::Vacant(entry) => {
                    (*entry.insert(next_project_id), true)
                }
                std::collections::btree_map::Entry::Occupied(entry) => (*entry.get(), false),
            };
            let project = pipeline
                .project
                .map_or("workspace", |project| project.name.as_str());
            let scope = format!(
                "{}{}Pipeline{index}",
                identifier(project),
                upper_initial(&identifier(&pipeline.ir.pipeline.name))
            );
            if render_services && let Some(project) = pipeline.project {
                services::append_project_services(
                    &mut out,
                    project,
                    services::ServiceRenderOptions {
                        project_id,
                        expose: self.config.should_emit_services(),
                        pipelines,
                        project_dir: pipeline.project_dir,
                    },
                )?;
            }
            match pipeline.ir.pipeline.mode {
                PipelineMode::Thin => append_thin_check(
                    &mut out,
                    &scope,
                    ThinCheck {
                        pipeline,
                        binary: self.config.cuenv_binary.as_deref(),
                    },
                )?,
                PipelineMode::Expanded => expanded::append_checks(
                    &mut out,
                    pipeline,
                    expanded::ExpandedConfig {
                        scope: &scope,
                        project_id,
                        default_image: self.config.default_image(),
                    },
                )?,
            }
        }
        out.push_str("}\n");
        Ok(out)
    }
}

impl Emitter for DaggerWorkspaceEmitter {
    fn emit_thin(&self, ir: &IntermediateRepresentation) -> EmitterResult<String> {
        self.emit_ir(ir, PipelineMode::Thin)
    }

    fn emit_expanded(&self, ir: &IntermediateRepresentation) -> EmitterResult<String> {
        self.emit_ir(ir, PipelineMode::Expanded)
    }

    fn format_name(&self) -> &'static str {
        "dagger"
    }

    fn file_extension(&self) -> &'static str {
        "dang"
    }
}

impl DaggerWorkspaceEmitter {
    fn emit_ir(
        &self,
        ir: &IntermediateRepresentation,
        mode: PipelineMode,
    ) -> EmitterResult<String> {
        let mut ir = ir.clone();
        ir.pipeline.mode = mode;
        let project_dir = PathBuf::from(ir.pipeline.project_path.as_deref().unwrap_or("."));
        self.emit_module(&[WorkspacePipeline {
            ir: &ir,
            project: None,
            project_dir: &project_dir,
            module_dir: Path::new("."),
            package: "cuenv",
        }])
    }
}

#[derive(Clone, Copy)]
struct ThinCheck<'a> {
    pipeline: &'a WorkspacePipeline<'a>,
    binary: Option<&'a str>,
}

fn append_thin_check(out: &mut String, scope: &str, check: ThinCheck<'_>) -> EmitterResult<()> {
    let ThinCheck { pipeline, binary } = check;
    let project_dir = relative_path(pipeline.project_dir)?;
    let module_dir = relative_path(pipeline.module_dir)?;
    let project_from_module = project_dir.strip_prefix(&module_dir).map_err(|_| {
        EmitterError::InvalidIR(
            "Dagger thin checks require the project inside its CUE module".to_string(),
        )
    })?;
    let module_mount = format!("{CONTAINER_ROOT}/{}", module_dir.display());
    let pipeline_name = &pipeline.ir.pipeline.name;
    let path = if project_from_module.as_os_str().is_empty() {
        "."
    } else {
        project_from_module
            .to_str()
            .ok_or_else(|| EmitterError::InvalidIR("non-UTF-8 project path".into()))?
    };
    let mut args = vec![
        "/usr/local/bin/cuenv",
        "ci",
        "--pipeline",
        pipeline_name,
        "--path",
        path,
        "--package",
        pipeline.package,
    ];
    if let Some(project) = pipeline.project {
        args.extend(["--project", &project.name]);
    }
    if let Some(environment) = pipeline.ir.pipeline.environment.as_deref() {
        args.extend(["--environment", environment]);
    }

    let _ = writeln!(out, "\n  pub {scope}(ws: Workspace!): Void @check {{");
    let _ = writeln!(out, "    container.from(\"buildpack-deps:bookworm-curl\")");
    if let Some(binary) = binary {
        let binary = relative_path(Path::new(binary))?;
        if binary.as_os_str().is_empty() {
            return Err(EmitterError::InvalidIR(
                "Dagger cuenvBinary must name a file".into(),
            ));
        }
        let source = format!("/{}", binary.display());
        let _ = writeln!(
            out,
            r#"      .withFile("/usr/local/bin/cuenv", ws.file({}), permissions: 493)"#,
            literal(&source)
        );
    } else {
        let _ = writeln!(
            out,
            "      .withExec({})",
            array(["sh", "-euc", &release_install_script()])
        );
    }
    out.push_str("      .withEnvVariable(\"CI\", \"true\")\n");
    let _ = writeln!(
        out,
        "      .withMountedDirectory(\"{CONTAINER_ROOT}\", ws.directory(\"/\"))"
    );
    let _ = writeln!(out, "      .withWorkdir({})", literal(&module_mount));
    let _ = writeln!(out, "      .withExec({})", array(args));
    out.push_str("      .sync\n    null\n  }\n");
    Ok(())
}

fn release_install_script() -> String {
    format!(
        concat!(
            "case $(uname -m) in x86_64|amd64) arch=x64;; aarch64|arm64) arch=arm64;; ",
            "*) echo 'Unsupported cuenv architecture' >&2; exit 1;; esac; ",
            "curl -fsSL -o /usr/local/bin/cuenv \"https://github.com/cuenv/cuenv/releases/download/{}/cuenv-linux-$arch\"; ",
            "chmod 0755 /usr/local/bin/cuenv; ",
            "if ! /usr/local/bin/cuenv ci --help | grep -q -- '--project'; then ",
            "echo 'This cuenv release cannot run a project-scoped check. Set ci.provider.dagger.cuenvBinary to a compatible build.' >&2; ",
            "exit 1; fi"
        ),
        env!("CARGO_PKG_VERSION"),
    )
}

fn relative_path(path: &Path) -> EmitterResult<PathBuf> {
    let mut relative = PathBuf::new();
    for component in path.components() {
        match component {
            Component::CurDir => {}
            Component::Normal(part) => relative.push(part),
            _ => {
                return Err(EmitterError::InvalidIR(format!(
                    "Dagger workspace paths must stay inside the repository: {}",
                    path.display()
                )));
            }
        }
    }
    Ok(relative)
}

fn literal(value: &str) -> String {
    serde_json::Value::String(value.to_string()).to_string()
}

fn array<'a>(items: impl IntoIterator<Item = &'a str>) -> String {
    let strings: Vec<_> = items.into_iter().map(literal).collect();
    format!("[{}]", strings.join(", "))
}

fn identifier(raw: &str) -> String {
    let mut words = raw
        .split(|ch: char| !ch.is_ascii_alphanumeric())
        .filter(|word| !word.is_empty());
    let Some(first) = words.next() else {
        return "unnamed".to_string();
    };
    let mut name = first.to_ascii_lowercase();
    if first.starts_with(|ch: char| ch.is_ascii_digit()) {
        name.insert(0, 'n');
    }
    for word in words {
        name.push_str(&upper_initial(&word.to_ascii_lowercase()));
    }
    name
}

fn upper_initial(raw: &str) -> String {
    let mut name = raw.to_string();
    if let Some(initial) = name.get_mut(..1) {
        initial.make_ascii_uppercase();
    }
    name
}

fn module_type(name: &str) -> EmitterResult<String> {
    if name.is_empty()
        || !name.starts_with(|ch: char| ch.is_ascii_alphabetic())
        || !name
            .chars()
            .all(|ch| ch.is_ascii_alphanumeric() || ch == '-' || ch == '_')
    {
        return Err(EmitterError::InvalidIR(format!(
            "invalid Dagger module name '{name}'"
        )));
    }
    Ok(upper_initial(&identifier(name)))
}

fn unsupported(feature: impl Into<String>) -> EmitterError {
    EmitterError::UnsupportedFeature {
        feature: feature.into(),
        emitter: "Dagger",
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use cuenv_ci::compiler::Compiler;
    use serde_json::json;

    #[test]
    fn expanded_project_checks_wait_for_dependencies_and_copy_declared_outputs()
    -> Result<(), Box<dyn std::error::Error>> {
        let config: Project = serde_json::from_value(json!({
            "name": "one",
            "runtime": {"type": "container", "image": "alpine:3.21"},
            "tasks": {
                "build": {"command": "make", "outputs": ["dist/*.txt"]},
                "test": {
                    "command": "test",
                    "args": ["-r", "dist/report.txt"],
                    "inputs": [{"task": "build"}],
                    "dependsOn": ["build", {"_name": "postgres", "kind": "service"}]
                }
            },
            "services": {
                "postgres": {
                    "type": "service",
                    "runtime": {"type": "container", "image": "postgres:17-alpine"},
                    "ports": [{"port": 5432}]
                }
            }
        }))?;
        let mut ir = Compiler::new(config.clone()).compile()?;
        ir.pipeline.mode = PipelineMode::Expanded;
        ir.pipeline.name = "default".to_string();
        let emitter = DaggerWorkspaceEmitter::new(DaggerCiConfig {
            emit_services: Some(false),
            module_name: Some("integration-ci".to_string()),
            module_path: Some("checks/local".to_string()),
            engine_version: Some("v1.0.0-beta.28".to_string()),
            ..DaggerCiConfig::default()
        });
        let files = emitter.emit_workspace(&[WorkspacePipeline {
            ir: &ir,
            project: Some(&config),
            project_dir: Path::new("apps/one"),
            module_dir: Path::new("."),
            package: "projects",
        }])?;
        assert!(files[0].content.contains("[modules.integration-ci]"));
        assert!(files[0].content.contains("source = \"./checks/local\""));
        assert_eq!(
            files[1].relative_path,
            Path::new("checks/local/dagger-module.toml")
        );
        assert!(
            files[1]
                .content
                .contains("engineVersion = \"v1.0.0-beta.28\"")
        );
        let dang = &files[2].content;
        assert!(dang.contains("type IntegrationCi"));
        assert!(dang.contains("ws.directory(\"/apps/one\")"));
        assert!(dang.contains("need0.sync"));
        assert!(dang.contains("need0.directory(\"/work/\"), include: [\"dist/*.txt\"]"));
        assert!(dang.contains(".withServiceBinding(\"postgres\", oneProject0Service0Postgres)"));
        assert!(!dang.contains("@up"));
        Ok(())
    }

    #[test]
    fn thin_checks_scope_same_named_pipelines_to_each_project()
    -> Result<(), Box<dyn std::error::Error>> {
        let first = Project::new("app-one");
        let second = Project::new("app_one");
        let ir = IntermediateRepresentation::new("lint");
        let pipelines = [&first, &second].map(|project| WorkspacePipeline {
            ir: &ir,
            project: Some(project),
            project_dir: Path::new(&project.name),
            module_dir: Path::new("."),
            package: "projects",
        });
        let emitter = DaggerWorkspaceEmitter::new(DaggerCiConfig {
            cuenv_binary: Some("tools/cuenv".to_string()),
            ..DaggerCiConfig::default()
        });
        let source = emitter.emit_module(&pipelines)?;
        assert!(source.contains("pub appOneLintPipeline0(ws: Workspace!): Void @check"));
        assert!(source.contains("pub appOneLintPipeline1(ws: Workspace!): Void @check"));
        assert!(source.contains("ws.file(\"/tools/cuenv\"), permissions: 493"));
        assert!(source.contains(
            "\"--path\", \"app-one\", \"--package\", \"projects\", \"--project\", \"app-one\""
        ));
        assert!(source.contains(
            "\"--path\", \"app_one\", \"--package\", \"projects\", \"--project\", \"app_one\""
        ));
        Ok(())
    }

    #[test]
    fn invalid_module_path_never_escapes_workspace() {
        let emitter = DaggerWorkspaceEmitter::new(DaggerCiConfig {
            module_path: Some("../outside".to_string()),
            ..DaggerCiConfig::default()
        });
        assert!(emitter.emit_workspace(&[]).is_err());
    }
}
